                <div className="absolute bottom-2 left-[12%] w-12 h-8 bg-gradient-to-tr from-[#7d7873] to-[#a8a29e] rounded-[45%_55%_50%_50%_/_50%_50%_40%_40%] rotate-2 shadow-sm" />
