                <div className="absolute bottom-1 right-[6%] w-14 h-12 bg-gradient-to-l from-[#75706b] to-[#9c9691] rounded-[45%_55%_60%_40%_/_30%_60%_40%_70%] rotate-[-4deg] shadow-sm z-[1]" />

