                        <g className="origin-bottom animate-sway" style={{ transformOrigin: '30% 100%', animationDelay: '-1.5s' }}>
                           <path d="M28 100 C 28 70 20 40 25 15 L 28 15 C 23 40 31 70 31 100 Z" fill="url(#plantGradient)" opacity="0.8" />
