            {/* --- LAYER 2: FOREGROUND PLANT (In Front of Fish) --- */}
            {/* Z-Index 35: In front of Fish (30), Behind Scenery (40) */}
            <div className="absolute inset-x-0 bottom-0 h-full z-[35] pointer-events-none">
                <div className="absolute bottom-4 left-[10%] w-24 h-[60%] opacity-80 mix-blend-multiply origin-bottom">
                     <svg className="w-full h-full overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none">
                        <defs>
                            <linearGradient id="plantGradientFg" x1="0.5" x2="0.5" y1="0" y2="1">
                                <stop offset="0%" stopColor="#4ade80" /> {/* green-400 */}
                                <stop offset="100%" stopColor="#14532d" /> {/* green-900 */}
                            </linearGradient>
                        </defs>

                        {/* Leaf 1 (Main Tall - Thicker Base) */}
                        <g className="origin-bottom animate-sway-slow" style={{ transformOrigin: '50% 100%' }}>
                           <path d="M 42 100 C 42 60 50 30 48 5 L 50 5 C 50 30 58 60 58 100 Z" fill="url(#plantGradientFg)" />
                        </g>
                     </svg>
                </div>
            </div>

            {/* --- SCENERY LAYER (Sand & Rocks) --- */}
            {/* Z-Index 40: Frontmost Layer (Covers plant bases & fish if low) */}
            <div className="absolute inset-x-0 bottom-0 h-20 z-40 pointer-events-none">

                {/* Background Rock (New Tall Rock) - Lighter color for depth, positioned behind */}
                {/* Adjusted right position from 4% to 8% to move it slightly left */}
                <div className="absolute bottom-1 right-[8%] w-16 h-14 bg-gradient-to-t from-[#a8a29e] to-[#d6d3d1] rounded-[30%_70%_70%_30%_/_30%_50%_50%_70%] rotate-[-8deg] opacity-90 z-0" />

                {/* Left Rock */}
                <div className="absolute bottom-2 left-[12%] w-12 h-8 bg-gradient-to-tr from-[#7d7873] to-[#a8a29e] rounded-[45%_55%_50%_50%_/_50%_50%_40%_40%] rotate-2 shadow-sm z-10" />

                {/* Right Small Rock (Foreground) */}
                <div className="absolute bottom-1 right-[18%] w-9 h-7 bg-gradient-to-tl from-[#8a8580] to-[#b5b0ab] rounded-[50%_50%_40%_60%] -rotate-3 shadow-sm z-10" />

                {/* Center Pebble */}
                <div className="absolute bottom-3 left-[45%] w-5 h-4 bg-gradient-to-t from-[#96918c] to-[#c2bdb8] rounded-full opacity-90 z-10" />

                {/* Sand Layer */}
                <svg className="absolute bottom-0 w-full h-full z-[20]" preserveAspectRatio="none" viewBox="0 0 100 100">
                    <defs>
                        <linearGradient id="sandGradient" x1="0" x2="0" y1="0" y2="1">
                            <stop offset="0%" stopColor="#f7eed9" /> {/* Very Light Sand */}
                            <stop offset="100%" stopColor="#ebe0c5" /> {/* Slightly Darker */}
                        </linearGradient>
                    </defs>
                    {/* Gentle Wave: Starts around y=75 (approx 15-20px high in h-20/80px container, which is ~10% of tank) */}
                    <path d="M0 100 L0 75 Q 30 82 50 78 T 100 72 L 100 100 Z" fill="url(#sandGradient)" />
                </svg>
            </div>

            {/* Hearts Layer */}
            {hearts.map(h => (
                <div 
                    key={h.id} 
                    className="absolute z-[60] pointer-events-none text-rose-500"
                    style={{ 
                        left: h.x, 
                        top: h.y,
                        '--tx': `${h.tx}px`,
                        '--rot': `${h.rot}deg`,
                        animation: 'heart-float 0.8s ease-out forwards'
                    } as React.CSSProperties}
                >
                    <svg viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5 drop-shadow-sm">
                        <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/>
                    </svg>
                </div>
            ))}

            {/* REWARD FEEDBACK (Dynamic Position) */}
            {rewardFeedback && clickCoords && (
                <div 
                    className="absolute z-50 pointer-events-none"
                    style={{ left: clickCoords.x, top: clickCoords.y - 20 }}
                >
                    <div 
                        className={`transition-all duration-300 ease-out ${
                            rewardExiting 
                            ? 'opacity-0 scale-90' 
                            : 'opacity-100 scale-100'
                        }`}
                    >
                        <div className="bg-white px-2.5 py-1 rounded-full shadow-lg flex items-center gap-1.5 border border-stone-100 animate-scale-in origin-center">
                            <>
                                <span className="text-xs font-bold text-stone-800">+{rewardFeedback.amount}</span>
                                <Icons.Diamond className="w-2.5 h-2.5 text-blue-500 fill-current" />
                            </>
                        </div>
                    </div>
                </div>
            )}

            {/* Tank Reflection */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-bl from-white/30 to-transparent pointer-events-none rounded-bl-full" />
        </div>
    );
};

import React, { useState, useEffect, useRef } from 'react';
import { Storage } from '../../utils/storage';
import { sounds } from '../../utils/sound';
import { Icons } from './Icons';
import { PepinoState } from '../../types';

interface FishTankProps {
    onRewardClaim: (amount: number) => void;
    showIntro?: boolean;
}

export const FishTank: React.FC<FishTankProps> = ({ onRewardClaim, showIntro = false }) => {
    const [pepinoState, setPepinoState] = useState<PepinoState>(Storage.getPepinoState());
    const [isGiftReady, setIsGiftReady] = useState(false);
    const [showGiftBubble, setShowGiftBubble] = useState(false); // Controls rendering for animation

    // Reward Feedback State
    const [rewardFeedback, setRewardFeedback] = useState<{amount: number} | null>(null);
    const [rewardExiting, setRewardExiting] = useState(false);
    const [clickCoords, setClickCoords] = useState<{x: number, y: number} | null>(null);

    // Hearts Interaction State
    const [hearts, setHearts] = useState<{id: number, x: number, y: number, tx: number, rot: number}[]>([]);

    // Intro State: 
    // 'waiting' (text visible) -> 'clearing' (text fades out) -> 
    // 'appearing' (fish pops in) -> 'active' (normal swim)
    const [introState, setIntroState] = useState<'waiting' | 'clearing' | 'appearing' | 'active'>(
        showIntro ? 'waiting' : 'active'
    );

    // Fish movement state
    const [fishPos, setFishPos] = useState({ x: 50, y: 50 }); // Percentage
    const [fishDirection, setFishDirection] = useState<'left' | 'right'>('right');

    // Refs for animation logic to avoid stale closures
    const fishPosRef = useRef({ x: 50, y: 50 });
    const containerRef = useRef<HTMLDivElement>(null);

    // Handle Intro Flow
    useEffect(() => {
        if (showIntro) {
            // 1. Wait 7 seconds with text overlay visible
            const timer1 = setTimeout(() => {
                setIntroState('clearing'); // Triggers text fade out (duration 700ms)

                // 2. Wait for text fade (700ms) + Empty Gap (500ms) = 1200ms
                setTimeout(() => {
                    setIntroState('appearing'); // Triggers fish pop
                    sounds.playPop(); // Sync improved pop sound

                    // 3. Switch to fully active state after rapid pop animation (300ms)
                    setTimeout(() => {
                        setIntroState('active');
                    }, 400); 
                }, 1200);
            }, 7000);
            return () => clearTimeout(timer1);
        }
    }, [showIntro]);

    // Timer check
    useEffect(() => {
        const checkTime = () => {
            const now = Date.now();
            const readyTime = pepinoState.lastGiftTime + pepinoState.nextGiftDelay;

            if (now >= readyTime) {
                setIsGiftReady(true);
            } else {
                setIsGiftReady(false);
            }
        };

        checkTime();
        const interval = setInterval(checkTime, 5000); 
        return () => clearInterval(interval);
    }, [pepinoState]);

    // Sync isGiftReady to showGiftBubble with delay for entrance animation
    useEffect(() => {
        if (isGiftReady) {
            // Delay showing the bubble so the user sees it appear (animate in)
            // even if it was ready instantly on mount.
            const t = setTimeout(() => setShowGiftBubble(true), 600);
            return () => clearTimeout(t);
        } else {
            setShowGiftBubble(false);
        }
    }, [isGiftReady]);

    // Random Swimming Logic
    useEffect(() => {
        let timeoutId: any;

        const moveFish = () => {
            const currentX = fishPosRef.current.x;

            // Generate new target position
            // X: 15-85% (avoid walls)
            const newX = 15 + Math.random() * 70;

            // Y: Limit to lower part (avoid top 50px)
            // Tank Height = 224px (h-56)
            // 50px is approx 22.3%
            // Fish center needs to be lower to clear the top border. 
            // 32% to 85% keeps it well within the water, below the 50px line and utilizing the bottom area (sand gone).
            const newY = 32 + Math.random() * 53; 

            // Determine direction based on CURRENT position vs NEW position
            const newDirection = newX > currentX ? 'right' : 'left';

            setFishDirection(newDirection);
            setFishPos({ x: newX, y: newY });

            // Update ref
            fishPosRef.current = { x: newX, y: newY };

            const delay = 4000 + Math.random() * 4000; // Slow, calm movement
            timeoutId = setTimeout(moveFish, delay);
        };

        // Initial delay: If showing intro, wait for sequence to finish (~9s total) before swimming
        // 7s wait + 1.2s clear/gap + 0.4s appear = ~8.6s. Safe buffer 9s.
        const startDelay = showIntro ? 9000 : 1000;
        timeoutId = setTimeout(moveFish, startDelay);

        return () => clearTimeout(timeoutId);
    }, [showIntro]); 

    const handleClaim = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (!isGiftReady || rewardFeedback) return;

        // Capture coordinates relative to tank
        if (containerRef.current) {
             const rect = containerRef.current.getBoundingClientRect();
             setClickCoords({
                 x: e.clientX - rect.left,
                 y: e.clientY - rect.top
             });
        }

        const minDelay = 7200000;
        const maxDelay = 10800000;
        const nextDelay = Math.floor(Math.random() * (maxDelay - minDelay + 1) + minDelay);

        Storage.updatePepinoGiftTime(nextDelay);
        setPepinoState(Storage.getPepinoState()); 
        setIsGiftReady(false);

        const r = Math.random();
        let amount = 5;

        // Reward Distribution:
        // 20 Diamonds: 5%
        // 15 Diamonds: 15%
        // 10 Diamonds: 30%
        // 5 Diamonds: 50%

        if (r < 0.05) amount = 20;
        else if (r < 0.20) amount = 15;
        else if (r < 0.50) amount = 10;
        else amount = 5;

        if (amount > 0) {
            // New "Bubbly" sound for gift
            sounds.playBubblePop();
            onRewardClaim(amount);
            showReward({ amount });
        }
    };

    const handlePepinoClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (containerRef.current) {
            const rect = containerRef.current.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            // Random horizontal movement (-60px to +60px)
            const tx = (Math.random() - 0.5) * 120;
            // Random rotation (-30deg to +30deg)
            const rot = (Math.random() - 0.5) * 60;

            const newHeart = { id: Date.now() + Math.random(), x, y, tx, rot };
            setHearts(prev => [...prev, newHeart]);

            setTimeout(() => {
                setHearts(prev => prev.filter(h => h.id !== newHeart.id));
            }, 800);
        }
    };

    const showReward = (feedback: {amount: number}) => {
        setRewardFeedback(feedback);
        setRewardExiting(false);

        // Show for 2 seconds total
        setTimeout(() => {
            setRewardExiting(true);
            setTimeout(() => {
                setRewardFeedback(null);
                setRewardExiting(false);
                setClickCoords(null);
            }, 300); 
        }, 1700);
    };

    // Derived state for visibility
    const isTextVisible = introState === 'waiting';
    const isFishVisible = introState === 'appearing' || introState === 'active';

    // Scale Logic: 0 during wait/clear, 1 during appear/active
    const scaleValue = (introState === 'waiting' || introState === 'clearing') ? 0 : 1;

    // Transition Duration Logic:
    // When popping (appearing), faster transition (300ms) for the scale to look snappy.
    // When active, slow transition (4000ms) for swimming.
    const transitionClass = introState === 'active' ? 'duration-[4000ms]' : 'duration-300';

    return (
        <div 
            ref={containerRef}
            // Size: w-24 h-16 (~20-25% smaller than original w-32 h-24)
            className="w-full h-56 relative rounded-[1.75rem] overflow-hidden bg-[#e0f7fa] shadow-xl mb-6 select-none animate-pop mx-auto"
        >
            <style>{`
                @keyframes heart-float {
                    0% { transform: translate(-50%, -50%) scale(1); opacity: 1; }
                    100% { transform: translate(calc(-50% + var(--tx)), calc(-50% - 75px)) scale(1.1) rotate(var(--rot)); opacity: 0; }
                }
            `}</style>

            {/* Clean Water Gradient */}
            <div className="absolute inset-0 bg-gradient-to-b from-[#e0f7fa] via-[#d1f4fa] to-[#b3e5fc]" />

            {/* --- LAYER 1: BACKGROUND PLANTS (Behind Fish) --- */}
            {/* Z-Index 5: Behind Fish (30) */}
            <div className="absolute inset-x-0 bottom-0 h-full z-[5] pointer-events-none">
                {/* Background Plants Cluster */}
                <div className="absolute bottom-4 left-[10%] w-24 h-[60%] opacity-80 mix-blend-multiply origin-bottom">
                     <svg className="w-full h-full overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none">
                        <defs>
                            <linearGradient id="plantGradientBg" x1="0.5" x2="0.5" y1="0" y2="1">
                                <stop offset="0%" stopColor="#4ade80" /> {/* green-400 */}
                                <stop offset="100%" stopColor="#14532d" /> {/* green-900 */}
                            </linearGradient>
                        </defs>

                        {/* Leaf 2 (Left - Thicker Base) */}
                        <g className="origin-bottom animate-sway" style={{ transformOrigin: '30% 100%', animationDelay: '-1.5s' }}>
                           <path d="M 24 100 C 24 70 30 40 25 15 L 27 15 C 33 30 40 60 36 100 Z" fill="url(#plantGradientBg)" opacity="0.8" />
                        </g>

                        {/* Leaf 3 (Right - Thicker Base) */}
                        <g className="origin-bottom animate-sway-slow" style={{ transformOrigin: '70% 100%', animationDelay: '-3s' }}>
                           <path d="M 69 100 C 69 70 75 40 78 15 L 80 15 C 85 40 81 70 81 100 Z" fill="url(#plantGradientBg)" opacity="0.9" />
                        </g>
                     </svg>
                </div>
            </div>

            {/* --- INTRO TEXT OVERLAY --- */}
            <div 
                className={`absolute inset-0 flex items-center justify-center p-4 z-40 transition-opacity duration-700 ${isTextVisible ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
            >
                <div className="bg-white/60 backdrop-blur-md p-6 rounded-2xl shadow-sm border border-white/40 text-center max-w-[90%]">
                    <p className="text-xl font-bold text-stone-800 mb-3 leading-tight">This is Pepino.</p>
                    <p className="text-sm font-medium text-stone-600 mb-1 leading-relaxed">He was around while Oku was being built.</p>
                    <p className="text-sm font-medium text-stone-600 leading-relaxed">Thanks for supporting the app — feel free to check on him anytime.</p>
                </div>
            </div>

            {/* PEPINO CONTAINER (Handles X/Y Position & Opacity) */}
            {/* Z-Index 30: In front of Back Plants (5), Behind Front Plant (35) */}
            <div 
                onClick={handlePepinoClick}
                className={`absolute w-12 h-8 z-30 cursor-pointer transition-none ${isFishVisible ? 'opacity-100' : 'opacity-0'}`}
                style={{ 
                    // Using calc for positioning to avoid translate(-50%, -50%) vibration on iOS
                    left: `calc(${fishPos.x}% - 1.5rem)`, 
                    top: `calc(${fishPos.y}% - 1rem)`,
                    // Use translate3d(0,0,0) ONLY for GPU layer promotion, not positioning
                    transform: 'translate3d(0,0,0)', 
                    WebkitBackfaceVisibility: 'hidden',
                    backfaceVisibility: 'hidden',
                    // Apply transition explicitly here to avoid Tailwind class conflicts
                    transition: `left ${introState === 'active' ? '4000ms' : '300ms'} ease-in-out, top ${introState === 'active' ? '4000ms' : '300ms'} ease-in-out, opacity 300ms ease-in-out`,
                    willChange: 'left, top'
                }}
            >
                 {/* POP IN ANIMATION WRAPPER (Handles Scale) */}
                 <div 
                    className="w-full h-full transition-transform duration-300 cubic-bezier(0.175, 0.885, 0.32, 1.275)"
                    style={{ transform: `scale(${scaleValue})` }}
                 >

                     {/* DIRECTION FLIPPER */}
                     <div 
                        className="w-full h-full transition-transform duration-500"
                        style={{ transform: fishDirection === 'left' ? 'scaleX(-1)' : 'scaleX(1)' }}
                     >
                         {/* WIGGLER */}
                         <div className="w-full h-full animate-wiggle">
                            {/* Updated Pepino with new SVG paths */}
                            <svg viewBox="344.5149 210.9059 74.9591 41.2278" className="w-full h-full drop-shadow-sm filter" style={{ filter: 'drop-shadow(0 4px 6px rgba(0,0,0,0.1))' }}>
                                <path d="M 373.193 239.648 C 379.513 254.112 400.131 252.185 404.661 240.061 C 393.45 240.02 396.193 239.089 386.193 239.648 L 373.193 239.648 Z" fill="#ef4444" opacity="0.95" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <path d="M 372.793 224.525 C 379.113 207.278 399.731 209.576 404.261 224.033 C 393.05 224.081 395.793 225.192 385.793 224.525 L 372.793 224.525 Z" fill="#ef4444" opacity="0.95" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <path d="M 394.515 231.681 C 379.515 206.681 344.428 201.406 344.515 231.681 C 344.565 261.131 379.515 256.681 394.515 231.681 Z" fill="#ef4444" opacity="0.95" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <path d="M 394.515 231.681 C 374.515 216.681 359.515 211.681 354.515 231.681 C 359.515 251.681 374.515 246.681 394.515 231.681 Z" fill="#b91c1c" opacity="0.15" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <ellipse cx="391.474" cy="231.681" rx="28" ry="11" fill="#dc2626" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <path d="M 401.174 234.169 C 395.84 239.502 397.84 240.836 407.174 238.169 L 401.174 234.169 Z" fill="#fca5a5" opacity="0.8" style={{strokeWidth: 1, transformOrigin: '402.719px 236.836px'}} transform="matrix(0.71619296, -0.69790214, 0.69790214, 0.71619296, 0.00000291, 0.0000368)"/>
                                <circle cx="411.874" cy="230.381" r="2.5" fill="black" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                                <circle cx="412.874" cy="229.381" r="0.8" fill="white" opacity="0.9" style={{strokeWidth: 1}} transform="matrix(1, 0, 0, 1, 0, -1.4210854715202004e-14)"/>
                            </svg>
                         </div>
                     </div>
                 </div>

                 {/* GIFT BUBBLE (Trigger) */}
                 {showGiftBubble && !isTextVisible && (
                        <div 
                            className="absolute -top-8 left-[58%] -translate-x-1/2 z-20" // Center relative to body
                        >
                             <div className="animate-scale-in origin-bottom">
                                <div 
                                    onClick={handleClaim}
                                    className="cursor-pointer hover:scale-110 transition-transform duration-200"
                                >
                                    <div className="bg-white/90 backdrop-blur-sm p-1.5 rounded-full shadow-md border border-blue-100/50">
                                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="#3b82f6" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                                            <rect x="3" y="8" width="18" height="4" rx="1" />
                                            <path d="M12 8v13" />
                                            <path d="M19 12v7a2 2 0 0 1-2 2H7a2 2 0 0 1-2-2v-7" />
                                            <path d="M7.5 8a2.5 2.5 0 0 1 0-5A4.8 8 0 0 1 12 8a4.8 8 0 0 1 4.5-5 2.5 2.5 0 0 1 0 5" />
                                        </svg>
                                    </div>
                                </div>
                             </div>
                        </div>
                 )}
            </div>

            {/* --- LAYER 2: FOREGROUND PLANT (In Front of Fish) --- */}
            {/* Z-Index 35: In front of Fish (30), Behind Scenery (40) */}
            <div className="absolute inset-x-0 bottom-0 h-full z-[35] pointer-events-none">
                <div className="absolute bottom-4 left-[10%] w-24 h-[60%] opacity-80 mix-blend-multiply origin-bottom">
                     <svg className="w-full h-full overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none">
                        <defs>
                            <linearGradient id="plantGradientFg" x1="0.5" x2="0.5" y1="0" y2="1">
                                <stop offset="0%" stopColor="#4ade80" /> {/* green-400 */}
                                <stop offset="100%" stopColor="#14532d" /> {/* green-900 */}
                            </linearGradient>
                        </defs>

                        {/* Leaf 1 (Main Tall - Thicker Base) */}
                        <g className="origin-bottom animate-sway-slow" style={{ transformOrigin: '50% 100%' }}>
                           <path d="M 42 100 C 42 60 50 30 48 5 L 50 5 C 50 30 58 60 58 100 Z" fill="url(#plantGradientFg)" />
                        </g>
                     </svg>
                </div>
            </div>

            {/* --- SCENERY LAYER (Sand & Rocks) --- */}
            {/* Z-Index 40: Frontmost Layer (Covers plant bases & fish if low) */}
            <div className="absolute inset-x-0 bottom-0 h-20 z-40 pointer-events-none">

                {/* Background Rock (New Tall Rock) - Lighter color for depth, positioned behind */}
                {/* Adjusted right position from 4% to 8% to move it slightly left */}
                <div className="absolute bottom-1 right-[8%] w-16 h-14 bg-gradient-to-t from-[#a8a29e] to-[#d6d3d1] rounded-[30%_70%_70%_30%_/_30%_50%_50%_70%] rotate-[-8deg] z-0" />

                {/* Left Rock */}
                <div className="absolute bottom-2 left-[12%] w-12 h-8 bg-gradient-to-tr from-[#7d7873] to-[#a8a29e] rounded-[45%_55%_50%_50%_/_50%_50%_40%_40%] rotate-2 shadow-sm z-10" />

                {/* Right Small Rock (Foreground) */}
                <div className="absolute bottom-1 right-[18%] w-9 h-7 bg-gradient-to-tl from-[#8a8580] to-[#b5b0ab] rounded-[50%_50%_40%_60%] -rotate-3 shadow-sm z-10" />

                {/* Center Pebble */}
                <div className="absolute bottom-3 left-[45%] w-5 h-4 bg-gradient-to-t from-[#96918c] to-[#c2bdb8] rounded-full z-10" />

                {/* Sand Layer */}
                <svg className="absolute bottom-0 w-full h-full z-[20]" preserveAspectRatio="none" viewBox="0 0 100 100">
                    <defs>
                        <linearGradient id="sandGradient" x1="0" x2="0" y1="0" y2="1">
                            <stop offset="0%" stopColor="#f7eed9" /> {/* Very Light Sand */}
                            <stop offset="100%" stopColor="#ebe0c5" /> {/* Slightly Darker */}
                        </linearGradient>
                    </defs>
                    {/* Gentle Wave: Starts around y=75 (approx 15-20px high in h-20/80px container, which is ~10% of tank) */}
                    <path d="M0 100 L0 75 Q 30 82 50 78 T 100 72 L 100 100 Z" fill="url(#sandGradient)" />
                </svg>
            </div>

            {/* Hearts Layer */}
            {hearts.map(h => (
                <div 
                    key={h.id} 
                    className="absolute z-[60] pointer-events-none text-rose-500"
                    style={{ 
                        left: h.x, 
                        top: h.y,
                        '--tx': `${h.tx}px`,
                        '--rot': `${h.rot}deg`,
                        animation: 'heart-float 0.8s ease-out forwards'
                    } as React.CSSProperties}
                >
                    <svg viewBox="0 0 24 24" fill="currentColor" className="w-5 h-5 drop-shadow-sm">
                        <path d="M12 21.35l-1.45-1.32C5.4 15.36 2 12.28 2 8.5 2 5.42 4.42 3 7.5 3c1.74 0 3.41.81 4.5 2.09C13.09 3.81 14.76 3 16.5 3 19.58 3 22 5.42 22 8.5c0 3.78-3.4 6.86-8.55 11.54L12 21.35z"/>
                    </svg>
                </div>
            ))}

            {/* REWARD FEEDBACK (Dynamic Position) */}
            {rewardFeedback && clickCoords && (
                <div 
                    className="absolute z-50 pointer-events-none"
                    style={{ left: clickCoords.x, top: clickCoords.y - 20 }}
                >
                    <div 
                        className={`transition-all duration-300 ease-out ${
                            rewardExiting 
                            ? 'opacity-0 scale-90' 
                            : 'opacity-100 scale-100'
                        }`}
                    >
                        <div className="bg-white px-2.5 py-1 rounded-full shadow-lg flex items-center gap-1.5 border border-stone-100 animate-scale-in origin-center">
                            <>
                                <span className="text-xs font-bold text-stone-800">+{rewardFeedback.amount}</span>
                                <Icons.Diamond className="w-2.5 h-2.5 text-blue-500 fill-current" />
                            </>
                        </div>
                    </div>
                </div>
            )}

            {/* Tank Reflection */}
            <div className="absolute top-0 right-0 w-32 h-32 bg-gradient-to-bl from-white/30 to-transparent pointer-events-none rounded-bl-full" />
        </div>
    );
};

import React, { useMemo } from 'react';
import { Board, Cell, AppSettings } from '../../types';

interface SudokuGridProps {
    board: Board;
    selectedCell: [number, number] | null;
    activeNumber: number | null;
    conflicts: Set<string>;
    revealingCell: {r: number, c: number} | null;
    animatingCell: {r: number, c: number, value: number} | null;
    isScanning: boolean;
    animatingSections: Set<string>;
    settings: AppSettings;
    numberColor: string;
    onCellClick: (e: React.MouseEvent, r: number, c: number) => void;
}

export const SudokuGrid: React.FC<SudokuGridProps> = ({
    board,
    selectedCell,
    activeNumber,
    conflicts,
    revealingCell,
    animatingCell,
    isScanning,
    animatingSections,
    settings,
    numberColor,
    onCellClick
}) => {
    const squareSize = 'min(96vw, 53dvh)';
    const mainFontSize = `calc(${squareSize} / 9 * 0.6)`;
    const noteFontSize = `calc(${squareSize} / 9 * 0.22)`;
    const noteLineHeight = `calc(${squareSize} / 9 * 0.25)`;

    // Calculate the currently highlighted value based on active input or selected cell
    const highlightedValue = useMemo(() => {
        if (activeNumber !== null) return activeNumber;
        if (selectedCell) {
            return board[selectedCell[0]][selectedCell[1]].value;
        }
        return null;
    }, [activeNumber, selectedCell, board]);

    const getCellClass = (cell: Cell, r: number, c: number) => {
        let classes = "w-full h-full flex items-center justify-center cursor-pointer select-none relative overflow-hidden ";
        const isConflict = conflicts.has(`${r}-${c}`);
        const isError = cell.isError;
        const isMarkedWrong = cell.isMarkedWrong;
        const isRevealed = cell.isRevealed;

        const isSelected = selectedCell ? (selectedCell[0] === r && selectedCell[1] === c) : false;

        // Check if cell matches highlighted value for background highlight
        let isSameValue = false;
        if (cell.value !== null && highlightedValue !== null) {
            isSameValue = cell.value === highlightedValue;
        }

        const isRelated = selectedCell && (selectedCell[0] === r || selectedCell[1] === c || (Math.floor(selectedCell[0]/3) === Math.floor(r/3) && Math.floor(selectedCell[1]/3) === Math.floor(c/3)));

        let bgClass = ''; 
        const isThisCellRevealing = revealingCell?.r === r && revealingCell?.c === c;

        if (isThisCellRevealing) {
            bgClass = ''; 
        } else if (isMarkedWrong) {
             // Scanner Detection: Bright Red Flash
             bgClass = 'bg-red-500 animate-pulse shadow-inner '; 
        } else if (isSelected && (isError || isConflict)) {
             // Selected Error: Noticeable Red
             bgClass = 'bg-red-200 dark:bg-red-900 '; 
        } else if (isError || isConflict) {
             // Error: Increased visibility
             bgClass = 'bg-red-100 dark:bg-red-900/50 ';
        } else if (isSelected) {
             bgClass = 'bg-blue-200 dark:bg-blue-500 '; // Selected: Blue 200 (Lighter)
        } else if (settings.highlight && isSameValue) {
             bgClass = 'bg-blue-100 dark:bg-blue-600/40 '; // Same Value: Blue 100
        } else if (settings.highlight && isRelated) {
             // Related: Grey (stone-100) instead of Blue
             bgClass = 'bg-stone-100 dark:bg-black/10 '; 
        } else if (isRevealed) {
             bgClass = 'bg-amber-100 '; 
        } else {
             bgClass = 'bg-t-board '; 
        }

        classes += bgClass;

        if (isThisCellRevealing) {
            classes += "animate-reveal-premium z-50 relative ";
        }

        if (cell.isFixed) {
            classes += "font-semibold text-stone-800 ";
        } else if (isRevealed) {
            classes += "font-semibold text-stone-800 ";
        } else {
            if (isMarkedWrong) {
                // Scanner Detection Text: White for contrast against bright red
                classes += "font-bold text-white ";
            } else if (isError || isConflict) {
                // Error Text: Darker red for visibility
                classes += "font-medium text-red-600 dark:text-red-300 ";
            } else {
                classes += "font-medium ";
            }
        }
        return classes;
    };

    const getSectionOverlayStyle = (sectionId: string) => {
        if (sectionId === 'full-board') {
            return {
                position: 'absolute' as const,
                pointerEvents: 'none' as const,
                zIndex: 60,
                top: 0,
                left: 0,
                width: '100%',
                height: '100%',
                borderWidth: '8px' // Make completion border more prominent
            };
        }

        const [type, idxStr] = sectionId.split('-');
        const index = parseInt(idxStr);
        const style: React.CSSProperties = { position: 'absolute', pointerEvents: 'none', zIndex: 60 };

        if (type === 'row') {
            style.top = `${(index / 9) * 100}%`;
            style.left = '0';
            style.width = '100%';
            style.height = `${100 / 9}%`;
        } else if (type === 'col') {
            style.left = `${(index / 9) * 100}%`;
            style.top = '0';
            style.height = '100%';
            style.width = `${100 / 9}%`;
        } else if (type === 'box') {
            const r = Math.floor(index / 3);
            const c = index % 3;
            style.top = `${(r * 3 / 9) * 100}%`;
            style.left = `${(c * 3 / 9) * 100}%`;
            style.width = `${100 / 3}%`;
            style.height = `${100 / 3}%`;
        }
        return style;
    };

    return (
        <div className="flex-none w-full flex flex-col items-center justify-start min-h-0 px-0 pb-2 pt-[10px]">
            <div 
                className="bg-stone-900 rounded-lg overflow-hidden relative flex-none shadow-lg border-[3px] border-stone-900" 
                style={{ 
                    width: squareSize, 
                    height: squareSize, 
                    maxWidth: '500px', 
                    maxHeight: '500px'
                }}
            >

            {/* Main Border Overlay Removed - Now handled by container border */}

            {isScanning && (
                <div className="absolute left-0 right-0 h-1 bg-red-500 shadow-[0_0_15px_rgba(239,68,68,0.8)] z-30 animate-scan pointer-events-none"></div>
            )}

            <div className="absolute inset-0 pointer-events-none z-20">
                <svg width="100%" height="100%" viewBox="0 0 9 9" fill="none" xmlns="http://www.w3.org/2000/svg" style={{ display: 'block' }}>
                    <defs><style>{`.grid-line-thin { stroke: #a8a29e; stroke-width: 0.05; } .grid-line-thick { stroke: #1c1917; stroke-width: 0.05; } `}</style></defs>
                    <line x1="1" y1="0" x2="1" y2="9" className="grid-line-thin" /><line x1="2" y1="0" x2="2" y2="9" className="grid-line-thin" />
                    <line x1="4" y1="0" x2="4" y2="9" className="grid-line-thin" /><line x1="5" y1="0" x2="5" y2="9" className="grid-line-thin" />
                    <line x1="7" y1="0" x2="7" y2="9" className="grid-line-thin" /><line x1="8" y1="0" x2="8" y2="9" className="grid-line-thin" />
                    <line x1="0" y1="1" x2="9" y2="1" className="grid-line-thin" /><line x1="0" y1="2" x2="9" y2="2" className="grid-line-thin" />
                    <line x1="0" y1="4" x2="9" y2="4" className="grid-line-thin" /><line x1="0" y1="5" x2="9" y2="5" className="grid-line-thin" />
                    <line x1="0" y1="7" x2="9" y2="7" className="grid-line-thin" /><line x1="0" y1="8" x2="9" y2="8" className="grid-line-thin" />
                    <line x1="3" y1="0" x2="3" y2="9" className="grid-line-thick" /><line x1="6" y1="0" x2="6" y2="9" className="grid-line-thick" />
                    <line x1="0" y1="3" x2="9" y2="3" className="grid-line-thick" /><line x1="0" y1="6" x2="9" y2="6" className="grid-line-thick" />
                </svg>
            </div>

            <div className="grid w-full h-full relative z-10" style={{ gridTemplateColumns: 'repeat(9, minmax(0, 1fr))', gridTemplateRows: 'repeat(9, minmax(0, 1fr))' }}>
            {board.map((row, rIndex) => row.map((cell, cIndex) => {
                    const isAnimating = animatingCell?.r === rIndex && animatingCell?.c === cIndex;

                    return (
                        <div 
                            key={`${rIndex}-${cIndex}`} 
                            className={getCellClass(cell, rIndex, cIndex)} 
                            onClick={(e) => {
                                e.stopPropagation();
                                onCellClick(e, rIndex, cIndex);
                            }} 
                            style={{ fontSize: mainFontSize }}
                        >
                        {(cell.value || isAnimating) ? (
                            <span className={`leading-none pt-[0.1em] relative z-10 ${!cell.isFixed && !cell.isError && !cell.isMarkedWrong && !cell.isRevealed ? numberColor : ''}`}>
                                {isAnimating ? animatingCell!.value : cell.value}
                            </span>
                        ) : (
                            <div className="grid grid-cols-3 grid-rows-3 w-full h-full p-[1px] pointer-events-none relative z-10">
                                {[1,2,3,4,5,6,7,8,9].map(n => {
                                    // BOLD NOTE LOGIC
                                    const isNoteActive = n === highlightedValue;
                                    const noteClass = cell.notes.includes(n) 
                                        ? (isNoteActive 
                                            ? 'text-stone-900 dark:text-stone-100 font-black scale-110 transition-transform' 
                                            : 'text-stone-500 font-medium')
                                        : 'invisible';

                                    return (
                                        <div key={n} className="flex items-center justify-center leading-none" style={{ fontSize: noteFontSize, lineHeight: noteLineHeight }}>
                                            <span className={noteClass}>{n}</span>
                                        </div>
                                    )
                                })}
                            </div>
                        )}
                        </div>
                    );
                })
            )}
            </div>

            {/* Section/Board Completion Borders */}
            {Array.from(animatingSections).map((sectionId: string) => (
                 <div 
                    key={sectionId} 
                    className={`absolute box-border border-emerald-300 shadow-[0_0_30px_rgba(16,185,129,0.9)] animate-section-complete ${sectionId === 'full-board' ? 'rounded-lg border-4' : 'rounded-sm border-2'}`}
                    style={getSectionOverlayStyle(sectionId)}
                 />
            ))}
         </div>
         </div>
    );
};

import { Haptics, ImpactStyle, NotificationType } from '@capacitor/haptics';

interface SoundProfile {
    id: string;
    type: 'sine' | 'square' | 'triangle' | 'sawtooth' | 'noise';
    uiClickFreq: number;
    uiTapFreq: number;
    numberFreqs: number[];
    popFreq: number;
    duration: number; // Base duration in seconds
    volumeScale: number;
    pitchDrop?: boolean;
    noiseFilterFreq?: number; // Center freq for noise bands
    tapFreqs?: number[]; // Frequencies for random variation on tap
}

const PROFILES: Record<string, SoundProfile> = {
    'snd-zen': {
        id: 'snd-zen',
        type: 'sine',
        uiClickFreq: 800, 
        uiTapFreq: 800,
        numberFreqs: Array(9).fill(600),
        popFreq: 400,
        duration: 0.035, 
        volumeScale: 1.0, 
        pitchDrop: true
    },
    'snd-paper': {
        id: 'snd-paper',
        type: 'noise', 
        uiClickFreq: 1200, 
        uiTapFreq: 1000,
        numberFreqs: Array(9).fill(1000), 
        popFreq: 800,
        duration: 0.05,
        volumeScale: 0.9,
        noiseFilterFreq: 800
    },
    'snd-wood': {
        id: 'snd-wood',
        type: 'sine', // Carrier is Sine, but we use FM synthesis
        uiClickFreq: 330, // E4 - Solid knock
        uiTapFreq: 392,   // G4
        tapFreqs: [330, 349, 392, 440], // Random log hits
        // E Minor Pentatonic (Forest/Mystic): E4, G4, A4, B4, D5, E5, G5, A5, B5
        numberFreqs: [329.63, 392.00, 440.00, 493.88, 587.33, 659.25, 783.99, 880.00, 987.77],
        popFreq: 164.8, // E3 (Deep Thud)
        duration: 0.15, 
        volumeScale: 1.4, // FM sounds can be quieter
        pitchDrop: false 
    },
    'snd-water': {
        id: 'snd-water',
        type: 'sine',
        uiClickFreq: 600,
        uiTapFreq: 700,
        // Whole Tone Scale (Dreamy/Fluid): C5, D5, E5, F#5, G#5, A#5, C6, D6, E6
        numberFreqs: [523.25, 587.33, 659.25, 739.99, 830.61, 932.33, 1046.50, 1174.66, 1318.51],
        popFreq: 400,
        duration: 0.1, 
        volumeScale: 0.9,
        pitchDrop: false // We use upward ramp
    },
    'snd-piano': {
        id: 'snd-piano',
        type: 'triangle', 
        uiClickFreq: 1046, // Fallback freq
        uiTapFreq: 523, // C5
        tapFreqs: [523.25, 587.33, 659.25, 783.99, 880.00], // C Major Pentatonic
        // Pentatonic Major Scale: C4, D4, E4, G4, A4, C5, D5, E5, G5
        numberFreqs: [261.63, 293.66, 329.63, 392.00, 440.00, 523.25, 587.33, 659.25, 783.99],
        popFreq: 196, // G3
        duration: 1.5, // Long sustained tail
        volumeScale: 0.6,
        pitchDrop: false
    }
};

class SoundController {
    private ctx: AudioContext | null = null;
    private soundEnabled: boolean = true;
    private vibrationEnabled: boolean = true;
    private activeProfile: SoundProfile = PROFILES['snd-zen'];

    setEnabled(enabled: boolean) {
        this.soundEnabled = enabled;
    }

    setVibrationEnabled(enabled: boolean) {
        this.vibrationEnabled = enabled;
    }

    setProfile(profileId: string) {
        // Migrations
        if (profileId === 'snd-glass') profileId = 'snd-water';
        if (profileId === 'snd-celeste') profileId = 'snd-piano';

        if (PROFILES[profileId]) {
            this.activeProfile = PROFILES[profileId];
        } else {
            this.activeProfile = PROFILES['snd-zen'];
        }
    }

    private getCtx() {
        if (!this.ctx) {
            const AudioContext = window.AudioContext || (window as any).webkitAudioContext;
            this.ctx = new AudioContext();
        }
        if (this.ctx.state === 'suspended') {
            this.ctx.resume();
        }
        return this.ctx;
    }

    private playNoiseBurst(centerFreq: number, duration: number, volume: number) {
        if (!this.soundEnabled) return;
        const ctx = this.getCtx();

        const bufferSize = ctx.sampleRate * duration;
        const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
        const data = buffer.getChannelData(0);
        for (let i = 0; i < bufferSize; i++) {
            data[i] = (Math.random() * 2 - 1);
        }

        const noise = ctx.createBufferSource();
        noise.buffer = buffer;

        const filter = ctx.createBiquadFilter();
        filter.type = 'bandpass';
        filter.Q.value = 0.7; 
        filter.frequency.setValueAtTime(centerFreq, ctx.currentTime);
        filter.frequency.exponentialRampToValueAtTime(centerFreq * 0.6, ctx.currentTime + duration);

        const gain = ctx.createGain();
        gain.gain.setValueAtTime(0, ctx.currentTime);
        gain.gain.linearRampToValueAtTime(volume, ctx.currentTime + 0.01);
        gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + duration);

        noise.connect(filter);
        filter.connect(gain);
        gain.connect(ctx.destination);

        noise.start();
        noise.stop(ctx.currentTime + duration + 0.1);
    }

    private playTone(
        freq: number, 
        duration: number, 
        volume: number, 
        type?: 'sine' | 'square' | 'triangle' | 'sawtooth',
        volumeScaleOverride?: number,
        disablePitchDrop: boolean = false,
        profileOverride?: SoundProfile
    ) {
        if (!this.soundEnabled) return;

        const profile = profileOverride || this.activeProfile;

        // Paper handling
        if (profile.id === 'snd-paper') {
            this.playNoiseBurst(profile.noiseFilterFreq || 800, duration, volume * profile.volumeScale);
            return;
        }

        const ctx = this.getCtx();
        const osc = ctx.createOscillator();
        const gain = ctx.createGain();

        // --- SYNTHESIS LOGIC ---

        if (profile.id === 'snd-wood') {
             // Forest/Log Synthesis (FM)
             // Carrier: Sine
             // Modulator: Sine (Ratio 2:1 for hollow, woody sound)
             osc.type = 'sine';

             const mod = ctx.createOscillator();
             const modGain = ctx.createGain();

             mod.type = 'sine';
             mod.frequency.setValueAtTime(freq * 2.0, ctx.currentTime);

             // Mod Index Envelope (The "Thwack")
             // High modulation at start (complex tone), fast decay to pure sine (resonance)
             const modDepth = freq * 0.8; 
             modGain.gain.setValueAtTime(modDepth, ctx.currentTime);
             modGain.gain.exponentialRampToValueAtTime(1, ctx.currentTime + 0.05);

             mod.connect(modGain);
             modGain.connect(osc.frequency);

             mod.start();
             mod.stop(ctx.currentTime + duration + 0.1);

             osc.connect(gain);

        } else if (profile.id === 'snd-piano') {
            // Piano Synthesis (Filtered Triangle)
            osc.type = 'triangle';
            const filter = ctx.createBiquadFilter();
            filter.type = 'lowpass';
            filter.Q.value = 0.5; 
            filter.frequency.setValueAtTime(Math.min(freq * 6, 8000), ctx.currentTime); 
            filter.frequency.exponentialRampToValueAtTime(freq * 1.5, ctx.currentTime + 0.3);
            osc.connect(filter);
            filter.connect(gain);

        } else {
            // Standard (Zen, Water)
            osc.type = type || (profile.type as any);
            osc.connect(gain);
        }

        // --- PITCH ENVELOPES ---

        if (profile.id === 'snd-water') {
            // Water Bubble Physics: Pitch Ramps UP ("Bloop")
            // Start lower, slide up quickly to target freq
            osc.frequency.setValueAtTime(freq * 0.5, ctx.currentTime);
            osc.frequency.linearRampToValueAtTime(freq, ctx.currentTime + 0.04);
            // Slight overshoot for bubble pop effect?
            osc.frequency.linearRampToValueAtTime(freq * 1.1, ctx.currentTime + duration);

        } else if (profile.id === 'snd-wood') {
             // Wood stays relatively constant pitch (FM handles the transient)
             osc.frequency.setValueAtTime(freq, ctx.currentTime);
        } else if (profile.pitchDrop && !disablePitchDrop) {
            // Zen/Standard Drop
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
            const dropTarget = Math.max(20, freq * 0.1); 
            osc.frequency.exponentialRampToValueAtTime(dropTarget, ctx.currentTime + duration);
        } else {
            osc.frequency.setValueAtTime(freq, ctx.currentTime);
        }

        const scale = volumeScaleOverride !== undefined ? volumeScaleOverride : profile.volumeScale;
        const vol = volume * scale;

        // --- AMPLITUDE ENVELOPES ---

        gain.gain.setValueAtTime(0, ctx.currentTime);

        if (profile.id === 'snd-piano') {
             gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + 0.015);
             gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
        } else if (profile.id === 'snd-wood') {
             // Perussive: Instant attack, fast exponential decay
             gain.gain.setValueAtTime(vol, ctx.currentTime);
             gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
        } else if (profile.id === 'snd-water') {
             // Bubble: Softer attack, quick decay
             gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + 0.02);
             gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
        } else {
             // Zen
             gain.gain.linearRampToValueAtTime(vol, ctx.currentTime + 0.002);
             gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
        }

        gain.connect(ctx.destination);

        osc.start();
        osc.stop(ctx.currentTime + duration + 0.2); 
    }

    playClick() {
        if (this.soundEnabled) {
            if (this.activeProfile.id === 'snd-piano') {
                const chord = [261.63, 329.63, 392.00]; 
                chord.forEach((f, i) => {
                    setTimeout(() => {
                        this.playTone(f, 0.6, 0.2, 'triangle', undefined, true); 
                    }, i * 12); 
                });
            } else if (this.activeProfile.id === 'snd-wood') {
                // Dry hollow click
                this.playTone(330, 0.1, 0.4, 'sine', undefined, true);
            } else if (this.activeProfile.id === 'snd-water') {
                // High bubble click
                this.playTone(800, 0.08, 0.3, 'sine', undefined, true);
            } else {
                this.playTone(this.activeProfile.uiClickFreq, this.activeProfile.duration, 0.4);
            }
        }

        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Light });
        }
    }

    playTap() {
        if (this.soundEnabled) {
            let freq = this.activeProfile.uiTapFreq;
            if (this.activeProfile.tapFreqs && this.activeProfile.tapFreqs.length > 0) {
                freq = this.activeProfile.tapFreqs[Math.floor(Math.random() * this.activeProfile.tapFreqs.length)];
            }
            this.playTone(freq, this.activeProfile.duration, 0.4);
        }
        if (this.vibrationEnabled) {
            Haptics.selectionStart();
        }
    }

    playNumber(num: number) {
        if (this.soundEnabled) {
            const freq = this.activeProfile.numberFreqs[num - 1] || 600;
            const vol = 0.6;
            this.playTone(freq, this.activeProfile.duration, vol);
        }
        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Medium });
        }
    }

    playPop() {
        if (this.soundEnabled) {
            // New Fun Pop: Quick upward sweep
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            osc.type = 'sine';
            // Start low, go high quickly
            osc.frequency.setValueAtTime(400, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(800, ctx.currentTime + 0.1);

            gain.gain.setValueAtTime(0, ctx.currentTime);
            gain.gain.linearRampToValueAtTime(0.5, ctx.currentTime + 0.01);
            gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1);

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.start();
            osc.stop(ctx.currentTime + 0.15);
        }
        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Light });
        }
    }

    playBubblePop() {
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            // "Bloop" - start lower, rise fast, short decay
            osc.type = 'sine';
            osc.frequency.setValueAtTime(300, ctx.currentTime);
            osc.frequency.exponentialRampToValueAtTime(600, ctx.currentTime + 0.1);

            gain.gain.setValueAtTime(0, ctx.currentTime);
            gain.gain.linearRampToValueAtTime(0.8, ctx.currentTime + 0.01); // Fast attack
            gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.1); // Short decay

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.start();
            osc.stop(ctx.currentTime + 0.15);
        }
        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Light });
        }
    }

    playPepinoTap() {
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const osc = ctx.createOscillator();
            const gain = ctx.createGain();

            // "Tiny Blip" - Cute and tactile
            // A5 (880Hz) to A6 (1760Hz) fast chirp
            osc.type = 'sine';
            osc.frequency.setValueAtTime(880, ctx.currentTime); 
            osc.frequency.exponentialRampToValueAtTime(1760, ctx.currentTime + 0.05); 

            gain.gain.setValueAtTime(0, ctx.currentTime);
            gain.gain.linearRampToValueAtTime(0.15, ctx.currentTime + 0.01); 
            gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.1); 

            osc.connect(gain);
            gain.connect(ctx.destination);

            osc.start();
            osc.stop(ctx.currentTime + 0.15);
        }
        // Light impact for tactility
        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Light });
        }
    }

    playWin() {
        if (this.soundEnabled) {
            const sequence = [1046.50, 1318.51, 1567.98, 2093.00]; 
            const timings = [0, 60, 120, 180]; 

            sequence.forEach((freq, i) => {
                setTimeout(() => {
                    const ctx = this.getCtx();
                    const osc = ctx.createOscillator();
                    const gain = ctx.createGain();
                    osc.type = 'sine';
                    osc.frequency.setValueAtTime(freq, ctx.currentTime);
                    gain.gain.setValueAtTime(0, ctx.currentTime);
                    gain.gain.linearRampToValueAtTime(0.25, ctx.currentTime + 0.01);
                    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + 0.2);
                    osc.connect(gain);
                    gain.connect(ctx.destination);
                    osc.start();
                    osc.stop(ctx.currentTime + 0.25);
                }, timings[i]);
            });
        }
        if (this.vibrationEnabled) {
            Haptics.notification({ type: NotificationType.Success });
        }
    }

    playLevelEnter() {
        if (!this.soundEnabled) return;

        const pid = this.activeProfile.id;

        if (pid === 'snd-paper') {
            this.playNoiseBurst(600, 0.15, 0.5);
            setTimeout(() => this.playNoiseBurst(1000, 0.1, 0.3), 100);

        } else if (pid === 'snd-wood') {
            // Forest Rattle: Random pentatonic notes
            const notes = [440, 587, 659, 783]; 
            notes.forEach((f, i) => {
                const delay = i * 40 + (Math.random() * 30);
                setTimeout(() => {
                    this.playTone(f, 0.1, 0.3, 'sine', undefined, true);
                }, delay);
            });

        } else if (pid === 'snd-water') {
             // River Stream: Rapid bubbling cascade
             const notes = [800, 700, 600, 500];
             notes.forEach((f, i) => {
                 setTimeout(() => this.playTone(f, 0.08, 0.3), i * 60);
             });

        } else if (pid === 'snd-piano') {
            const notes = [261.63, 329.63, 392.00, 493.88];
            notes.forEach((f, i) => {
                setTimeout(() => this.playTone(f, 1.0, 0.4, 'triangle', undefined, false), i * 60);
            });
        } else {
            const d = 0.035; 
            this.playTone(1200, d, 0.5, 'sine', undefined, true); 
            setTimeout(() => {
                this.playTone(1600, d, 0.5, 'sine', undefined, true);
            }, 60); 
        }
    }

    playZap() {
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const now = ctx.currentTime;

            const bufferSize = ctx.sampleRate * 0.2;
            const buffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
            const data = buffer.getChannelData(0);
            for (let i = 0; i < bufferSize; i++) {
                data[i] = Math.random() * 2 - 1;
            }

            const noise = ctx.createBufferSource();
            noise.buffer = buffer;

            const noiseFilter = ctx.createBiquadFilter();
            noiseFilter.type = 'bandpass';
            noiseFilter.Q.value = 1.0;
            noiseFilter.frequency.setValueAtTime(600, now);
            noiseFilter.frequency.exponentialRampToValueAtTime(3500, now + 0.15); 

            const noiseGain = ctx.createGain();
            noiseGain.gain.setValueAtTime(0, now);
            noiseGain.gain.linearRampToValueAtTime(0.35, now + 0.04);
            noiseGain.gain.exponentialRampToValueAtTime(0.001, now + 0.18);

            noise.connect(noiseFilter);
            noiseFilter.connect(noiseGain);
            noiseGain.connect(ctx.destination);
            noise.start(now);
            noise.stop(now + 0.2);

            const osc = ctx.createOscillator();
            const gain = ctx.createGain();
            osc.type = 'sine';
            osc.frequency.setValueAtTime(800, now);
            osc.frequency.exponentialRampToValueAtTime(1400, now + 0.1); 

            gain.gain.setValueAtTime(0, now);
            gain.gain.linearRampToValueAtTime(0.25, now + 0.02);
            gain.gain.exponentialRampToValueAtTime(0.001, now + 0.25);

            osc.connect(gain);
            gain.connect(ctx.destination);
            osc.start(now);
            osc.stop(now + 0.25);
        }

        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Heavy });
        }
    }

    playScan() {
        if (this.soundEnabled) {
            const ctx = this.getCtx();
            const now = ctx.currentTime;
            const duration = 1.2;

            const tikOsc = ctx.createOscillator();
            const tikGain = ctx.createGain();
            tikOsc.type = 'square';
            tikOsc.frequency.setValueAtTime(2500, now);
            tikGain.gain.setValueAtTime(0, now);
            for(let i = 0; i < 12; i++) {
                const t = now + (i * (duration / 12));
                tikGain.gain.setTargetAtTime(0.06, t, 0.005);
                tikGain.gain.setTargetAtTime(0, t + 0.02, 0.005);
            }
            tikOsc.connect(tikGain);
            tikGain.connect(ctx.destination);
            tikOsc.start(now);
            tikOsc.stop(now + duration);

            const bzzOsc = ctx.createOscillator();
            const bzzGain = ctx.createGain();
            bzzOsc.type = 'sawtooth';
            bzzOsc.frequency.setValueAtTime(120, now);
            bzzOsc.frequency.exponentialRampToValueAtTime(400, now + duration);
            bzzGain.gain.setValueAtTime(0, now);
            bzzGain.gain.linearRampToValueAtTime(0.045, now + 0.2); 
            bzzGain.gain.exponentialRampToValueAtTime(0.001, now + duration);
            bzzOsc.connect(bzzGain);
            bzzGain.connect(ctx.destination);
            bzzOsc.start(now);
            bzzOsc.stop(now + duration);

            const chimeOsc = ctx.createOscillator();
            const chimeGain = ctx.createGain();
            chimeOsc.type = 'sine';
            chimeOsc.frequency.setValueAtTime(783.99, now + 0.3); 
            chimeOsc.frequency.exponentialRampToValueAtTime(1046.50, now + duration); 
            chimeGain.gain.setValueAtTime(0, now);
            chimeGain.gain.setTargetAtTime(0.0675, now + 0.4, 0.2); 
            chimeGain.gain.exponentialRampToValueAtTime(0.001, now + duration);
            chimeOsc.connect(chimeGain);
            chimeGain.connect(ctx.destination);
            chimeOsc.start(now + 0.3);
            chimeOsc.stop(now + duration);

            const bufferSize = ctx.sampleRate * 0.5;
            const noiseBuffer = ctx.createBuffer(1, bufferSize, ctx.sampleRate);
            const output = noiseBuffer.getChannelData(0);
            for (let i = 0; i < bufferSize; i++) {
                output[i] = Math.random() * 2 - 1;
            }
            const whiteNoise = ctx.createBufferSource();
            whiteNoise.buffer = noiseBuffer;
            const noiseGain = ctx.createGain();
            noiseGain.gain.setValueAtTime(0, now + duration - 0.4);
            noiseGain.gain.linearRampToValueAtTime(0.016875, now + duration - 0.2);
            noiseGain.gain.exponentialRampToValueAtTime(0.001, now + duration);
            whiteNoise.connect(noiseGain);
            noiseGain.connect(ctx.destination);
            whiteNoise.start(now + duration - 0.4);
        }

        if (this.vibrationEnabled) {
            Haptics.impact({ style: ImpactStyle.Medium });
            setTimeout(() => { if (this.vibrationEnabled) Haptics.impact({ style: ImpactStyle.Light }); }, 600);
        }
    }

    playReveal() {
        if (!this.soundEnabled) return;
        this.playTone(523.25, 0.15, 0.4, 'sine', 1.0, true);
        setTimeout(() => this.playTone(1046.50, 0.4, 0.3, 'sine', 1.0, true), 100);
    }

    playPreview(profileId: string) {
        if (!this.soundEnabled) return;

        if (profileId === 'snd-glass') profileId = 'snd-water';
        if (profileId === 'snd-celeste') profileId = 'snd-piano';

        const profile = PROFILES[profileId];
        if (!profile) return;

        // Play the 5th number frequency as a sample
        const freq = profile.numberFreqs[4]; 

        if (profile.type === 'noise') {
             this.playNoiseBurst(profile.noiseFilterFreq || 800, profile.duration, 0.6);
        } else {
             // Preview uses playTone logic directly to match synthesis
             // Pass the profile explicitly to playTone so it uses the correct synthesis logic
             this.playTone(freq, profile.duration, 0.5, undefined, undefined, undefined, profile);
        }
    }
}

export const sounds = new SoundController();

import React, { useState, useEffect, useRef } from 'react';
import { Storage } from '../../utils/storage';
import { sounds } from '../../utils/sound';
import { Icons } from './Icons';
import { PepinoState } from '../../types';

interface FishTankProps {
    onRewardClaim: (amount: number) => void;
    showIntro?: boolean;
}

export const FishTank: React.FC<FishTankProps> = ({ onRewardClaim, showIntro = false }) => {
    const [pepinoState, setPepinoState] = useState<PepinoState>(Storage.getPepinoState());
    const [isGiftReady, setIsGiftReady] = useState(false);
    const [showGiftBubble, setShowGiftBubble] = useState(false); // Controls rendering for animation

    // Reward Feedback State
    const [rewardFeedback, setRewardFeedback] = useState<{amount: number} | null>(null);
    const [rewardExiting, setRewardExiting] = useState(false);
    const [clickCoords, setClickCoords] = useState<{x: number, y: number} | null>(null);

    // Hearts Interaction State
    const [hearts, setHearts] = useState<{id: number, x: number, y: number, tx: number, rot: number}[]>([]);

    // Intro State: 
    // 'waiting' (text visible) -> 'clearing' (text fades out) -> 
    // 'appearing' (fish pops in) -> 'active' (normal swim)
    const [introState, setIntroState] = useState<'waiting' | 'clearing' | 'appearing' | 'active'>(
        showIntro ? 'waiting' : 'active'
    );

    // Fish movement state
    const [fishPos, setFishPos] = useState({ x: 50, y: 50 }); // Percentage
    const [fishDirection, setFishDirection] = useState<'left' | 'right'>('right');

    // Refs for animation logic to avoid stale closures
    const fishPosRef = useRef({ x: 50, y: 50 });
    const containerRef = useRef<HTMLDivElement>(null);

    // Handle Intro Flow
    useEffect(() => {
        if (showIntro) {
            // 1. Wait 7 seconds with text overlay visible
            const timer1 = setTimeout(() => {
                setIntroState('clearing'); // Triggers text fade out (duration 700ms)

                // 2. Wait for text fade (700ms) + Empty Gap (500ms) = 1200ms
                setTimeout(() => {
                    setIntroState('appearing'); // Triggers fish pop
                    sounds.playPop(); // Sync improved pop sound

                    // 3. Switch to fully active state after rapid pop animation (300ms)
                    setTimeout(() => {
                        setIntroState('active');
                    }, 400); 
                }, 1200);
            }, 7000);
            return () => clearTimeout(timer1);
        }
    }, [showIntro]);

    // Timer check
    useEffect(() => {
        const checkTime = () => {
            const now = Date.now();
            const readyTime = pepinoState.lastGiftTime + pepinoState.nextGiftDelay;

            if (now >= readyTime) {
                setIsGiftReady(true);
            } else {
                setIsGiftReady(false);
            }
        };

        checkTime();
        const interval = setInterval(checkTime, 5000); 
        return () => clearInterval(interval);
    }, [pepinoState]);

    // Sync isGiftReady to showGiftBubble with delay for entrance animation
    useEffect(() => {
        if (isGiftReady) {
            // Delay showing the bubble so the user sees it appear (animate in)
            // even if it was ready instantly on mount.
            const t = setTimeout(() => setShowGiftBubble(true), 600);
            return () => clearTimeout(t);
        } else {
            setShowGiftBubble(false);
        }
    }, [isGiftReady]);

    // Random Swimming Logic
    useEffect(() => {
        let timeoutId: any;

        const moveFish = () => {
            const currentX = fishPosRef.current.x;

            // Generate new target position
            // X: 15-85% (avoid walls)
            const newX = 15 + Math.random() * 70;

            // Y: Limit to lower part (avoid top 50px)
            // Tank Height = 224px (h-56)
            // 50px is approx 22.3%
            // Fish center needs to be lower to clear the top border. 
            // 32% to 85% keeps it well within the water, below the 50px line and utilizing the bottom area (sand gone).
            const newY = 32 + Math.random() * 53; 

            // Determine direction based on CURRENT position vs NEW position
            const newDirection = newX > currentX ? 'right' : 'left';

            setFishDirection(newDirection);
            setFishPos({ x: newX, y: newY });

            // Update ref
            fishPosRef.current = { x: newX, y: newY };

            const delay = 4000 + Math.random() * 4000; // Slow, calm movement
            timeoutId = setTimeout(moveFish, delay);
        };

        // Initial delay: If showing intro, wait for sequence to finish (~9s total) before swimming
        // 7s wait + 1.2s clear/gap + 0.4s appear = ~8.6s. Safe buffer 9s.
        const startDelay = showIntro ? 9000 : 1000;
        timeoutId = setTimeout(moveFish, startDelay);

        return () => clearTimeout(timeoutId);
    }, [showIntro]); 

    const handleClaim = (e: React.MouseEvent) => {
        e.stopPropagation();
        if (!isGiftReady || rewardFeedback) return;

        // Capture coordinates relative to tank
        if (containerRef.current) {
             const rect = containerRef.current.getBoundingClientRect();
             setClickCoords({
                 x: e.clientX - rect.left,
                 y: e.clientY - rect.top
             });
        }

        const minDelay = 7200000;
        const maxDelay = 10800000;
        const nextDelay = Math.floor(Math.random() * (maxDelay - minDelay + 1) + minDelay);

        Storage.updatePepinoGiftTime(nextDelay);
        setPepinoState(Storage.getPepinoState()); 
        setIsGiftReady(false);

        const r = Math.random();
        let amount = 5;

        // Reward Distribution:
        // 20 Diamonds: 5%
        // 15 Diamonds: 15%
        // 10 Diamonds: 30%
        // 5 Diamonds: 50%

        if (r < 0.05) amount = 20;
        else if (r < 0.20) amount = 15;
        else if (r < 0.50) amount = 10;
        else amount = 5;

        if (amount > 0) {
            // New "Bubbly" sound for gift
            sounds.playBubblePop();
            onRewardClaim(amount);
            showReward({ amount });
        }
    };

    const handlePepinoClick = (e: React.MouseEvent) => {
        e.stopPropagation();
        sounds.playPepinoTap(); // Play cute tap sound
        if (containerRef.current) {
            const rect = containerRef.current.getBoundingClientRect();
            const x = e.clientX - rect.left;
            const y = e.clientY - rect.top;

            // Random horizontal movement (-60px to +60px)
            const tx = (Math.random() - 0.5) * 120;
            // Random rotation (-30deg to +30deg)
            const rot = (Math.random() - 0.5) * 60;

            const newHeart = { id: Date.now() + Math.random(), x, y, tx, rot };
            setHearts(prev => [...prev, newHeart]);

            setTimeout(() => {
                setHearts(prev => prev.filter(h => h.id !== newHeart.id));
            }, 800);
        }
    };

    const showReward = (feedback: {amount: number}) => {
        setRewardFeedback(feedback);
        setRewardExiting(false);

        // Show for 2 seconds total
        setTimeout(() => {
            setRewardExiting(true);
            setTimeout(() => {
                setRewardFeedback(null);
                setRewardExiting(false);
                setClickCoords(null);
            }, 300); 
        }, 1700);
    };

    // Derived state for visibility
    const isTextVisible = introState === 'waiting';
    const isFishVisible = introState === 'appearing' || introState === 'active';

    // Scale Logic: 0 during wait/clear, 1 during appear/active
    const scaleValue = (introState === 'waiting' || introState === 'clearing') ? 0 : 1;

    // Transition Duration Logic:
    // When popping (appearing), faster transition (300ms) for the scale to look snappy.
    // When active, slow transition (4000ms) for swimming.
    const transitionClass = introState === 'active' ? 'duration-[4000ms]' : 'duration-300';

    return (
        <div 
            ref={containerRef}
            // Size: w-24 h-16 (~20-25% smaller than original w-32 h-24)
            className="w-full h-56 relative rounded-[1.75rem] overflow-hidden bg-[#e0f7fa] shadow-xl mb-6 select-none animate-pop mx-auto"
        >
            <style>{`
                @keyframes heart-float {
                    0% { transform: translate(-50%, -50%) scale(1); opacity: 1; }
                    100% { transform: translate(calc(-50% + var(--tx)), calc(-50% - 75px)) scale(1.1) rotate(var(--rot)); opacity: 0; }
                }
            `}</style>

            {/* Clean Water Gradient */}
            <div className="absolute inset-0 bg-gradient-to-b from-[#e0f7fa] via-[#d1f4fa] to-[#b3e5fc]" />

            {/* --- LAYER 1: BACKGROUND PLANTS (Behind Fish) --- */}
            {/* Z-Index 5: Behind Fish (30) */}
            <div className="absolute inset-x-0 bottom-0 h-full z-[5] pointer-events-none">
                {/* Background Plants Cluster */}
                {/* Added translate3d(0,0,0) to force layer promotion and fix vibration on iOS */}
                <div 
                    className="absolute bottom-4 left-[10%] w-24 h-[60%] opacity-80 mix-blend-multiply origin-bottom"
                    style={{ transform: 'translate3d(0,0,0)' }}
                >
                     <svg className="w-full h-full overflow-visible" viewBox="0 0 100 100" preserveAspectRatio="none">
                        <defs>
                            <linearGradient id="plantGradientBg" x1="0.5" x2="0.5" y1="0" y2="1">
                                <stop offset="0%" stopColor="#4ade80" /> {/* green-400 */}
                                <stop offset="100%" stopColor="#14532d" /> {/* green-900 */}
                            </linearGradient>
                        </defs>

                        {/* Leaf 2 (Left - Thicker Base) */}
                        <g 
                            className="origin-bottom animate-sway" 
                            style={{ transformOrigin: '30% 100%', animationDelay: '-1.5s', willChange: 'transform' }}
                        >
                           <path d="M 24 100 C 24 70 30 40 25 15 L 27 15 C 33 30 40 60 36 100 Z" fill="url(#plantGradientBg)" opacity="0.8" />
                        </g>

                        {/* Leaf 3 (Right - Thicker Base) */}
                        <g 
                            className="origin-bottom animate-sway-slow" 
                            style={{ transformOrigin: '70% 100%', animationDelay: '-3s', willChange: 'transform' }}
                        >
                           <path d="M 69 100 C 69 70 75 40 78 15 L 80 15 C 85 40 81 70 81 100 Z" fill="url(#plantGradientBg)" opacity="0.9" />
                        </g>
                     </svg>
                </div>
            </div>

            {/* --- INTRO TEXT OVERLAY --- */}
            <div 
                className={`absolute inset-0 flex items-center justify-center p-4 z-40 transition-opacity duration-700 ${isTextVisible ? 'opacity-100' : 'opacity-0 pointer-events-none'}`}
            >
                <div className="bg-white/60 backdrop-blur-md p-6 rounded-2xl shadow-sm border border-white/40 text-center max-w-[90%]">
                    <p className="text-xl font-bold text-stone-800 mb-3 leading-tight">This is Pepino.</p>
                    <p className="text-sm font-medium text-stone-600 mb-1 leading-relaxed">He was around while Oku was being built.</p>
                    <p className="text-sm font-medium text-stone-600 leading-relaxed">Thanks for supporting the app — feel free to check on him anytime.</p>
                </div>
            </div>

            {/* PEPINO CONTAINER (Handles X/Y Position & Opacity) */}
            {/* Z-Index 30: In front of Back Plants (5), Behind Front Plant (35) */}
            <div 
                onClick={handlePepinoClick}
                className={`absolute w-12 h-8 z-30 cursor-pointer transition-none ${isFishVisible ? 'opacity-100' : 'opacity-0'}`}
                style={{ 
                    // Using calc for positioning to avoid translate(-50%, -50%) vibration on iOS
                    left: `calc(${fishPos.x}% - 1.5rem)`, 
                    top: `calc(${fishPos.y}% - 1rem)`,
                    // Use translate3d(0,0,0) ONLY for GPU layer promotion, not positioning
                    transform: 'translate3d(0,0,0)', 
                    WebkitBackfaceVisibility: 'hidden',
                    backfaceVisibility: 'hidden',
                    // Apply transition explicitly here to avoid Tailwind class conflicts
                    transition: `left ${introState === 'active' ? '4000ms' : '300ms'} ease-in-out, top ${introState === 'active' ? '4000ms' : '300ms'} ease-in-out, opacity 300ms ease-in-out`,
                    willChange: 'left, top'
