                            {/* Interface */}
                            <div className="mb-6 space-y-3">
                                <label className="block text-sm font-bold text-t-secondary uppercase tracking-widest mb-2 ml-1">Interface</label>

                                <SettingRow 
                                    sKey="showTimer" 
                                    icon={Icons.Clock} 
                                    title="Show Timer" 
                                    desc="Display the elapsed time during gameplay."
                                    settings={settings}
                                    onToggle={onToggle}
