                                <SettingRow 
                                    sKey="generateReplay" 
                                    icon={Icons.Video} 
                                    title="Generate Replay" 
                                    desc="Create a shareable video of your solution."
                                    settings={settings}
                                    onToggle={onToggle}
                                />

                                <SettingRow 
                                    sKey="highlight" 
                                    icon={Icons.Eye} 
                                    title="Highlight Areas" 
                                    desc="Highlight rows, columns, and boxes for the selected cell."
