                                <span className="text-[9px] text-stone-300 dark:text-stone-600 font-mono">v1.0.0</span>
                            </div>
                        </div>
                    )}

                    {/* Render DOC VIEW if active */}
                    {activeDoc && (
                        <div className="flex-1 flex flex-col bg-white dark:bg-stone-900 animate-slide-up min-h-0 h-full">
